-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.chapter_info(p_phone text DEFAULT NULL::text, p_at_member_id text DEFAULT NULL::text, p_chapter text DEFAULT NULL::text)
 RETURNS TABLE(chapter text, member_count bigint, asker_is_member boolean, leads jsonb, about text, categories text[], live_stats jsonb, page_url text, geo text, region text, asker_city text, asker_state text, note text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare v_n int; v_asker text; v_city text; v_state text;
begin
  if p_at_member_id is not null then
    select count(*), max(mz.at_member_id) into v_n, v_asker from digest.member_attributes mz
      where mz.at_member_id = p_at_member_id and digest.is_active_member_status(mz.membership_status);
  else
    select count(*), max(mz.at_member_id) into v_n, v_asker from digest.member_identity mz
      where mz.at_member_id = digest.resolve_asker(p_phone) and digest.is_active_member_status(mz.membership_status);
  end if;
  if v_n < 1 then return; end if;

  select ma.city, ma.state into v_city, v_state
  from digest.member_attributes ma where ma.at_member_id = v_asker limit 1;

  return query
  with cmap(code, disp) as (values
    ('US','US'),('USA','US'),('United States','US'),
    ('CA','Canada'),('Canada','Canada'),
    ('GB','UK'),('UK','UK'),('United Kingdom','UK'),
    ('AU','Australia'),('Australia','Australia'),
    ('SG','Singapore'),('Singapore','Singapore'),
    ('TH','Thailand'),('Thailand','Thailand'),
    ('DE','Germany'),('Germany','Germany'),
    ('FR','France'),('France','France'),
    ('ES','Spain'),('Spain','Spain'),
    ('IT','Italy'),('Italy','Italy'),
    ('NL','Netherlands'),('Netherlands','Netherlands'),
    ('BE','Belgium'),('Belgium','Belgium'),
    ('SE','Sweden'),('Sweden','Sweden'),
    ('NO','Norway'),('Norway','Norway'),
    ('DK','Denmark'),('Denmark','Denmark'),
    ('FI','Finland'),('Finland','Finland'),
    ('EE','Estonia'),('Estonia','Estonia'),
    ('LV','Latvia'),('Latvia','Latvia'),
    ('LT','Lithuania'),('Lithuania','Lithuania'),
    ('PL','Poland'),('Poland','Poland'),
    ('CZ','Czechia'),('Czechia','Czechia'),('Czech Republic','Czechia'),
    ('SK','Slovakia'),('Slovakia','Slovakia'),
    ('AT','Austria'),('Austria','Austria'),
    ('CH','Switzerland'),('Switzerland','Switzerland'),
    ('PT','Portugal'),('Portugal','Portugal'),
    ('GR','Greece'),('Greece','Greece'),
    ('CY','Cyprus'),('Cyprus','Cyprus'),
    ('MT','Malta'),('Malta','Malta'),
    ('BG','Bulgaria'),('Bulgaria','Bulgaria'),
    ('RO','Romania'),('Romania','Romania'),
    ('HU','Hungary'),('Hungary','Hungary'),
    ('SI','Slovenia'),('Slovenia','Slovenia'),
    ('HR','Croatia'),('Croatia','Croatia'),
    ('TR','Turkey'),('Turkey','Turkey'),
    ('IL','Israel'),('Israel','Israel'),
    ('AE','UAE'),('United Arab Emirates','UAE'),
    ('IN','India'),('India','India'),
    ('CN','China'),('China','China'),
    ('HK','Hong Kong'),('Hong Kong','Hong Kong'),
    ('TW','Taiwan'),('Taiwan','Taiwan'),
    ('JP','Japan'),('Japan','Japan'),
    ('KR','South Korea'),('South Korea','South Korea'),
    ('MX','Mexico'),('Mexico','Mexico'),
    ('BR','Brazil'),('Brazil','Brazil'),
    ('PR','Puerto Rico'),('Puerto Rico','Puerto Rico'),
    ('NZ','New Zealand'),('New Zealand','New Zealand'),
    ('IE','Ireland'),('Ireland','Ireland'),
    ('IS','Iceland'),('Iceland','Iceland'),
    ('UA','Ukraine'),('Ukraine','Ukraine'),
    ('BY','Belarus'),('Belarus','Belarus'),
    ('PA','Panama'),('Panama','Panama'),
    ('CO','Colombia'),('Colombia','Colombia'),
    ('VN','Vietnam'),('Vietnam','Vietnam'),
    ('MY','Malaysia'),('Malaysia','Malaysia'),
    ('PH','Philippines'),('Philippines','Philippines'),
    ('ID','Indonesia'),('Indonesia','Indonesia')
  ),
  pop as (
    select ma.at_member_id,
           mp.at_fields->>'Chapter Affiliation' as chapter_raw,
           ma.rev_band, ma.channel_mix, ma.tiktok_seller,
           ma.business_model, ma.age_band, ma.sku_count, ma.brands_count, ma.started_year,
           coalesce(cm.disp, nullif(trim(ma.country),'')) as country_c,
           case when mp.at_fields->>'Most Recent Revenue' ~ '^\[[0-9.,Ee+ ]*\]$'
                  then ((mp.at_fields->>'Most Recent Revenue')::jsonb->>0)::numeric
                when mp.at_fields->>'Most Recent Revenue' ~ '^[0-9.]+$'
                  then (mp.at_fields->>'Most Recent Revenue')::numeric
           end as mrr,
           case when mp.at_fields->>'Total Employee Count' ~ '^[0-9]+$'
                  then (mp.at_fields->>'Total Employee Count')::numeric end as emp,
           case when mp.at_fields->>'# of Years for Member' ~ '^[0-9.]+$'
                  then (mp.at_fields->>'# of Years for Member')::numeric end as tenure
    from digest.member_attributes ma
    left join digest.member_profiles mp on mp.at_member_id = ma.at_member_id
    left join cmap cm on cm.code = trim(ma.country)
    where ma.membership_status in ('Current Member','New Member','Pending Group Entrance','Current Member- Not Renewing')
  ),
  chap as (
    select p.at_member_id, trim(ch.one) as chapter
    from pop p cross join lateral regexp_split_to_table(
      coalesce(digest.attr_clean(p.chapter_raw), ''), ',[[:space:]]*') ch(one)
    where trim(ch.one) not in ('', 'No Chapter Affiliation', 'Chapter Leads')
  ),
  stats as (
    select c.chapter as ch_name,
           count(distinct c.at_member_id) as n,
           (select jsonb_object_agg(t.k, t.v order by t.v desc) from (
              select mn.niche as k, count(distinct mn.at_member_id) as v
              from digest.member_niches mn join chap c2 on c2.at_member_id = mn.at_member_id
              where c2.chapter = c.chapter group by 1 order by 2 desc limit 6) t) as top_niches,
           (select jsonb_object_agg(t.k, t.v order by t.v desc) from (
              select coalesce(nullif(trim(p2.rev_band),''),'(none on file)') as k, count(*) as v
              from pop p2 join chap c3 on c3.at_member_id = p2.at_member_id
              where c3.chapter = c.chapter group by 1) t) as band_mix,
           (select coalesce(jsonb_object_agg(t.k, t.v order by t.v desc), '{}'::jsonb) from (
              select u.ch as k, count(distinct p4.at_member_id) as v
              from pop p4 join chap c5 on c5.at_member_id = p4.at_member_id
              cross join lateral unnest(coalesce(p4.channel_mix, '{}'::text[])) u(ch)
              where c5.chapter = c.chapter group by 1) t) as channels,
           (select coalesce(jsonb_object_agg(t.k, t.v order by t.v desc), '{}'::jsonb) from (
              select u.bm as k, count(distinct p6.at_member_id) as v
              from pop p6 join chap c7 on c7.at_member_id = p6.at_member_id
              cross join lateral unnest(coalesce(p6.business_model, '{}'::text[])) u(bm)
              where c7.chapter = c.chapter group by 1) t) as business_models,
           (select coalesce(jsonb_object_agg(t.k, t.v order by t.v desc), '{}'::jsonb) from (
              select p7.country_c as k, count(*) as v
              from pop p7 join chap c8 on c8.at_member_id = p7.at_member_id
              where c8.chapter = c.chapter and p7.country_c is not null group by 1) t) as countries,
           (select coalesce(jsonb_object_agg(t.k, t.v order by t.v desc), '{}'::jsonb) from (
              select p8.age_band as k, count(*) as v
              from pop p8 join chap c9 on c9.at_member_id = p8.at_member_id
              where c9.chapter = c.chapter and p8.age_band is not null group by 1) t) as age_mix,
           count(distinct c.at_member_id) filter (where p3.tiktok_seller) as tiktok_n,
           count(distinct c.at_member_id) filter (where coalesce(array_length(p3.channel_mix,1),0) > 0) as channel_reporters,
           avg(case when p3.started_year between 1980 and 2026
                    then extract(year from current_date) - p3.started_year end) as yib_avg,
           percentile_cont(0.5) within group (order by p3.sku_count) filter (where p3.sku_count is not null) as sku_median,
           avg(p3.brands_count) as brands_avg,
           sum(p3.mrr) as mrr_sum, avg(p3.mrr) as mrr_avg,
           sum(p3.emp) as emp_sum, avg(p3.emp) as emp_avg,
           avg(p3.tenure) as tenure_avg
    from chap c
    join pop p3 on p3.at_member_id = c.at_member_id
    group by c.chapter
  )
  select cc.chapter, coalesce(s.n, 0)::bigint,
         exists(select 1 from chap c4 where c4.chapter = cc.chapter and c4.at_member_id = v_asker),
         cc.leads, cc.about, cc.categories,
         jsonb_build_object(
           'members', coalesce(s.n, 0),
           'top_niches', coalesce(s.top_niches, '{}'::jsonb),
           'band_mix', coalesce(s.band_mix, '{}'::jsonb),
           'channels', coalesce(s.channels, '{}'::jsonb)
                       || case when coalesce(s.tiktok_n,0) > 0
                               then jsonb_build_object('TikTok Shop', s.tiktok_n)
                               else '{}'::jsonb end,
           'channel_reporters', s.channel_reporters,
           'business_models', coalesce(s.business_models, '{}'::jsonb),
           'countries', coalesce(s.countries, '{}'::jsonb),
           'age_mix', coalesce(s.age_mix, '{}'::jsonb),
           'avg_years_in_business', round(s.yib_avg, 1),
           'median_sku_count', round(s.sku_median::numeric, 0),
           'avg_brands', round(s.brands_avg, 1),
           'ttm_revenue_sum', case when s.mrr_sum is null then null
                                   else '$' || round(s.mrr_sum / 1000000)::text || 'M' end,
           'ttm_revenue_avg', case when s.mrr_avg is null then null
                                   else '$' || round(s.mrr_avg / 1000000, 1)::text || 'M' end,
           'employees_sum', s.emp_sum, 'employees_avg', round(s.emp_avg, 1),
           'avg_tenure_years', round(s.tenure_avg, 1)),
         cc.page_url, cc.geo, cc.region,
         v_city, v_state,
         'ALL numbers are LIVE from member records (aggregates only, never raw member values; ttm from Most Recent Revenue; channels/business_models/countries/age_mix are member counts - quote channel counts against channel_reporters; avg_years_in_business = years running the business, avg_tenure_years = years in MDS). The chapter page supplies only leads (names/roles/photos - public), about text and the link. Lead emails/phones are never available. asker_city/asker_state = the ASKER''s own on-file location for closest-to-me.'::text
  from digest.chapters_catalog cc
  left join stats s on s.ch_name = cc.chapter
  where p_chapter is null
     or cc.chapter ilike ('%' || p_chapter || '%')
     or cc.site_name ilike ('%' || p_chapter || '%')
  order by coalesce(s.n,0) desc;
end $function$
